@pragma('vm:entry-point')
List<int> mazeTorchCells(String cells, int torches) {
  var out = <int>[];
  var parts = cells.isEmpty ? <String>[] : cells.split('/');
  for (var i = 0; i < parts.length; i++) {
    if ('*'.allMatches(parts[i]).length == torches) out.add(i);
  }
  return out;
}

@pragma('vm:entry-point')
void main() {
  assert(mazeTorchCells("**/*/**", 2).toString() == "[0, 2]");
  assert(mazeTorchCells("room/door", 0).length == 2);
  assert(mazeTorchCells("", 1).toString() == "[]");
  print('All tests passed!');
}

tests:
void main() {
  final candidate = mazeTorchCells;

  expect(candidate('', 0), []);
  expect(candidate('cell', 0), [0]);
  expect(candidate('*', 1), [0]);
  expect(candidate('**/*/**', 2), [0, 2]);
  expect(candidate('**/*/**', 1), [1]);
  expect(candidate('a*/b/**c/d*e*', 2), [2, 3]);
  expect(candidate('///', 0), [0, 1, 2, 3]);
  expect(candidate('trap*/safe/pit**', 0), [1]);
  expect(candidate('x*/**y/*z*/end', 2), [1, 2]);
  expect(candidate('torch***/mid*/tail', 3), [0]);
}

