String theaterSightlineStreak(List<int> rows) {
  var best = 0, run = 0, last = -1;
  for (final r in rows) {
    run = r >= last ? run + 1 : 1;
    if (run > best) best = run;
    last = r;
  }
  return 'R$best';
}

