@pragma('vm:entry-point')
int compressedLogBurstChecksum(String log) {
  int sum = 0, run = 1;
  for (int i = 0; i < log.length; i++) {
    int c = log.codeUnitAt(i);
    if (c >= 48 && c <= 57) run = c - 48; else sum += c * run;
  }
  return sum % 97;
}

@pragma('vm:entry-point')
