@pragma('vm:entry-point')
List<String> neighboringBracketSeeds(List<int> seeds, int challengerSeed, String bracket) {
  int l = 0, r = seeds.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (seeds[m] < challengerSeed) l = m + 1; else r = m;
  }
  return [
    '$bracket:${l == 0 ? -1 : seeds[l - 1]}',
    '$bracket:${l == seeds.length ? -1 : seeds[l]}'
  ];
}

@pragma('vm:entry-point')
void main() {
  assert(neighboringBracketSeeds([1, 4, 8], 5, 'East').join('|') == 'East:4|East:8');
  assert(neighboringBracketSeeds([], 3, 'West').toString() == '[West:-1, West:-1]');
  assert(neighboringBracketSeeds([2, 6, 9], 10, 'Final').last == 'Final:-1');
  print('All tests passed!');
}

tests:
