  final candidate = neighboringBracketSeeds;

  expect(candidate([], 7, 'A'), ['A:-1', 'A:-1']);
  expect(candidate([3], 3, 'B'), ['B:-1', 'B:3']);
  expect(candidate([3], 4, 'B'), ['B:3', 'B:-1']);
  expect(candidate([1, 4, 8, 12], 0, 'East'), ['East:-1', 'East:1']);
  expect(candidate([1, 4, 8, 12], 1, 'East'), ['East:-1', 'East:1']);
  expect(candidate([1, 4, 8, 12], 5, 'East'), ['East:4', 'East:8']);
  expect(candidate([1, 4, 8, 12], 12, 'East'), ['East:8', 'East:12']);
