bool hasBalancedUniqueSquareColors(List<String> squares) {
  var seen = <String>{};
  var score = 0;
  for (var s in squares) {
    if (seen.add(s)) {
      score += ((s.codeUnitAt(0) + s.codeUnitAt(1)) & 1) == 0 ? 1 : -1;
    }
  }
  return score == 0;
}

