@pragma('vm:entry-point')
List<num> morsePulseWindows(String code, int width) {
  var r = <num>[], s = 0.0;
  for (var i = 0; i < code.length; i++) {
    s += 0.5 + 0.5 * (46 - code.codeUnitAt(i));
    if (i >= width) s -= 0.5 + 0.5 * (46 - code.codeUnitAt(i - width));
    if (i + 1 >= width) r.add(s / width);
  }
  return r;
}

@pragma('vm:entry-point')
void main() {
  assert(morsePulseWindows('.-', 2).toString() == '[0.75]');
  assert(morsePulseWindows('....', 2).length == 3);
  assert(morsePulseWindows('--..', 4).toString() == '[0.75]');
  print('All tests passed!');
}

