  expect(candidate('----', 2), [1.0, 1.0, 1.0]);
  expect(candidate('....', 2), [0.5, 0.5, 0.5]);
  expect(candidate('.-.-', 2), [0.75, 0.75, 0.75]);
  expect(candidate('--..', 4), [0.75]);
