int countCircularGreenConflicts(int phaseBits, int rotation) {
  int s = rotation & 7;
  int r = ((phaseBits << s) | (phaseBits >> (8 - s))) & 255;
  int x = r & ((r << 1) | (r >> 7));
  int c = 0;
  while (x != 0) {
    c += x & 1;
    x >>= 1;
  }
  return c;
}

