int widestIrrigableStrip(List<int> drynessDebt, int waterLimit) {
  var left = 0, sum = 0, best = 0;
  for (var right = 0; right < drynessDebt.length; right++) {
    sum += drynessDebt[right];
    while (sum > waterLimit) sum -= drynessDebt[left++];
    if (right - left + 1 > best) best = right - left + 1;
  }
  return best;
}

