List<num> vividRgbSpan(List<int> rgb) {
  var l = 0, d = 0, bS = 0, bL = 0;
  for (var r = 0; r < rgb.length; r++) {
    d += (rgb[r] >> 7) ^ 1;
    while (d > 1) d -= (rgb[l++] >> 7) ^ 1;
    if (r - l + 1 > bL) { bL = r - l + 1; bS = l; }
  }
  return [bS, bL];
}

