int playlistMoodFlips(int playlist) {
  if (playlist < 2) return 0;
  var bits = playlist.bitLength;
  var x = playlist ^ (((playlist << 1) & ((1 << bits) - 1)) | (playlist >> (bits - 1)));
  var flips = 0;
  while (x != 0) {
    flips += x & 1;
    x >>= 1;
  }
  return flips;
}

