bool hasCollapsedMazeGap(List<int> cells) {
  if (cells.isEmpty) return false;
  var l = 0, r = cells.length;
  while (l < r) {
    var m = (l + r) >> 1;
    cells[m] == cells[0] + m ? l = m + 1 : r = m;
