int countEdgeTripleRounds(int packedRounds) {
  int wins = 0;
  while (packedRounds != 0) {
    int m = packedRounds & 63, c = m - ((m >> 1) & 21);
    c = (c & 51) + ((c >> 2) & 51);
    if ((((c + (c >> 4)) & 15) == 3) && (m & 33) == 33) wins++;
    packedRounds >>= 6;
  }
  return wins;
}

