String widestStepwiseBarcode(String code) {
  var s = 0, b = 0, l = code.isEmpty ? 0 : 1;
  for (var i = 1; i < code.length; i++) {
    if ((code.codeUnitAt(i) - code.codeUnitAt(i - 1)).abs() != 1) s = i;
    if (i - s + 1 > l) {
      b = s;
      l = i - s + 1;
    }
  }
  return code.substring(b, b + l);
}

