@pragma('vm:entry-point')
String summarizeLogSkips(String logDays, int alertGap) {
  if (logDays.isEmpty) return 'empty';
  var a = logDays.split(','), flagged = 0, total = 0;
  for (var i = 1; i < a.length; i++) {
    var miss = int.parse(a[i]) - int.parse(a[i - 1]) - 1;
    if (miss >= alertGap) flagged += miss;
    total += miss;
  }
  return '$flagged/$total';
}

@pragma('vm:entry-point')
