double asciiRowEdgeInk(int rows) {
  var score = 0;
  for (var n = rows; n != 0; n >>= 8) {
    var b = n & 255;
    var c = b - ((b >> 1) & 85);
    c = (c & 51) + ((c >> 2) & 51);
    c = (c + (c >> 4)) & 15;
    score += ((b ^ (b >> 7)) & 1) == 0 ? c : -c;
  }
  return score / 2.0;
}

