import 'dart:math';

List<int> bracketRequestedSeat(List<int> chart) {
  if (chart.isEmpty) return [];
  var t = chart.last, l = 0, r = chart.length - 2;
  while (l <= r) {
    var m = (l + r) >> 1;
    if (chart[m] < t) l = m + 1; else r = m - 1;
  }
  return [chart[max(r, 0)], chart[min(l, chart.length - 2)]];
}

