String locateHashOverflowBucket(List<int> buckets, int limit) {
  int l = 0, r = buckets.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (buckets[m] < limit) l = m + 1; else r = m;
  }
  return l == buckets.length ? 'stable' : 'b$l:${buckets[l]}';
}

