int findMissingPacketTier(List<int> sizes) {
  if (sizes.isEmpty) return 0;
  var l = 0, r = sizes.length - 1, base = sizes[0];
  while (l <= r) {
    var m = (l + r) >> 1;
    if (sizes[m] == base + m * 8) l = m + 1;
    else r = m - 1;
  }
  return base + l * 8;
}

