@pragma('vm:entry-point')
bool packetBurstUsesMtu(String trace, int mtu) {
  int n = 0, seen = 0;
  bool ok = trace.isNotEmpty;
  for (var c in trace.codeUnits) {
    if (c == 124) { ok = ok & (seen > 0) & (n == mtu); n = 0; seen = 0; }
    else { n = n * 10 + c - 48; seen++; }
  }
  return ok & (seen > 0) & (n == mtu);
}

@pragma('vm:entry-point')
void main() {
  assert(packetBurstUsesMtu('64|64', 64) == true);
  assert(packetBurstUsesMtu('64|63', 64) == false);
  assert(packetBurstUsesMtu('|64', 64) == false);
  print('All tests passed!');
