List<int> merchantPackWindow(List<int> loads, int capacity) {
  var s = 0, sum = 0, best = -1, at = 0;
  for (var i = 0; i < loads.length; i++) {
    sum += loads[i];
    if (sum > capacity) sum -= loads[s++];
    if (i - s > best) { best = i - s; at = s; }
  }
  return [at, at + best + 1];
}

