String locateMoistureBand(List<int> bands, int moisture) {
  int l = 0, r = bands.length;
  while (l < r) {
    int m = (l + r) >> 1;
    if (bands[m] < moisture) l = m + 1; else r = m;
  }
  return l < bands.length && bands[l] == moisture ? 'band $l' : 'gap $l';
