int countSecureLeadMoments(List<int> voteChanges, int margin) {
  int lead = 0, count = 0;
  for (final change in voteChanges) {
    lead += change;
    if (lead >= margin) count++;
    lead = lead < 0 ? 0 : lead;
  }
  return count;
}

