List<int> recursiveRgbEdgeMix(List<int> pixels) {
  return pixels.isEmpty
      ? []
      : pixels.length == 1
          ? [pixels[0]]
          : [((pixels.first + pixels.last) ~/ 2), ...recursiveRgbEdgeMix(pixels.sublist(1, pixels.length - 1))];
}

