@pragma('vm:entry-point')
List<String> rankTelemetryBursts(List<String> samples) {
  var v = [...samples];
  v.sort((a, b) {
    var da = int.parse(a.split(':')[1]);
    var db = int.parse(b.split(':')[1]);
    return da == db ? a.compareTo(b) : db.compareTo(da);
  });
  return v.map((e) => e.split(':')[0]).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(rankTelemetryBursts([]).length == 0);
  assert(rankTelemetryBursts(['north:4','east:9']).toString() == '[east, north]');
  assert(rankTelemetryBursts(['b:3','a:3','c:-1']).toString() == '[a, b, c]');
  print('All tests passed!');
}

